import{_ as t,o as s,c as e,a5 as n}from"./chunks/framework.CslsFoWx.js";const g=JSON.parse('{"title":"Multi-magasins","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/14-multi-store.md","filePath":"generated/modules/14-multi-store.md","lastUpdated":null}'),d={name:"modules/14-multi-store.md"};function r(i,a,o,p,l,u){return s(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="multi-magasins" tabindex="-1">Multi-magasins <a class="header-anchor" href="#multi-magasins" aria-label="Permalink to &quot;Multi-magasins&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 3 · <a href="/VendoraSystem-docs/specs/14-multi-store">spécification complète</a></span></p><p>Gestion de plusieurs magasins sous un même tenant : administration des magasins, catalogue partagé avec surcharges locales, rôles par magasin, transferts de stock avec stock en transit, clients et fournisseurs partagés, scoping de la synchronisation. Le socle multi-tenant existe (RLS, rôles par magasin, appareil rattaché à un magasin, pull filtré par magasin, thème de marque hérité, invitation multi-magasins) ; création et archivage des magasins (lot R1) et transferts de stock entre magasins (lot 3.11a) sont faits ; prix, TVA et disponibilité par magasin (lot 3.11b) et comparaison des magasins (lot 3.11c) aussi.</p><div class="kpis"><div><b>16</b><span>faites</span></div><div><b>3</b><span>partielles</span></div><div><b>1</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="magasins" tabindex="-1">Magasins <a class="header-anchor" href="#magasins" aria-label="Permalink to &quot;Magasins&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Liste des magasins</strong><br><span class="muted">Voir au back-office les magasins du tenant (nom, profil, devise, fuseau), isolés par la RLS.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-01</td><td>0.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-lots-front-existants">📷</a></td></tr><tr><td><strong>Création et modification d&#39;un magasin</strong><br><span class="muted">Créer un magasin (nom, profil, devise, fuseau, TVA par défaut, adresse, horaires) avec activation des modules du profil, puis le modifier.<br><i>Lot R1 : POST /stores (propriétaire, administrateurs) dans la limite de la formule (« Magasins en plus » depuis la console) ; le propriétaire et les administrateurs y reçoivent leur rôle ; page Magasins du back-office.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-01, RG-MSTORE-16</td><td>R1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r1-magasins-appareils">📷</a></td></tr><tr><td><strong>Archivage d&#39;un magasin</strong><br><span class="muted">Archiver un magasin (jamais de suppression), refusé (409) tant qu&#39;une session de caisse ou un transfert est en cours.<br><i>Lot R1 : archivage et remise en service ; refusé pour le dernier magasin actif et tant que des appareils sont actifs (message qui les nomme) ; magasin archivé lisible, plus aucun appairage. Lot 3.11a : refusé aussi tant qu&#39;un transfert est en cours (numéros cités).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-02</td><td>R1, 3.11a</td><td><a href="/VendoraSystem-docs/preuves/2026-10-31-r1-magasins-appareils">📷</a></td></tr><tr><td><strong>Paramètres propres à chaque magasin</strong><br><span class="muted">Porter par magasin ses réglages : devise et fuseau, thème et langue, politiques d&#39;encaissement à la table, de vente et d&#39;authentification, plan de salle, postes, connecteurs de paiement.<br><i>Nom, profil, fuseau modifiables, devise tant qu&#39;aucune vente (lot R1) ; restent les horaires d&#39;ouverture et la TVA par défaut du magasin.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td>RG-MSTORE-16</td><td>1.x, 2.15, 2.16, 2.23, 2.24, 2.25, R1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-encaissement-table">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-connecteurs-paiement">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-equipe">📷</a></td></tr><tr><td><strong>Sélecteur de magasin au back-office</strong><br><span class="muted">Choisir le magasin sur lequel se scope chaque vue du back-office, ou « Tous les magasins » pour OWNER / ADMIN.<br><i>Refonte UX4 (01/11) : sélecteur de magasin global dans l&#39;en-tête du back-office (« Tous les magasins » pour OWNER / ADMIN, mémorisé, lien ?store= lu à l&#39;ouverture), branché sur le tableau de bord, les rapports de ventes, les marges, les rapports de stock, la comparaison des magasins et les exports comptables ; les autres pages gardent leur sélecteur jusqu&#39;à leur reprise (UX5).</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-17</td><td>1.x, 2.23, UX4</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-ux4-back-office-coquille">📷</a></td></tr></tbody></table><h2 id="equipe" tabindex="-1">Équipe <a class="header-anchor" href="#equipe" aria-label="Permalink to &quot;Équipe&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Rôles par magasin</strong><br><span class="muted">Donner à un utilisateur un rôle par magasin (table store_roles), gérer l&#39;équipe de chaque magasin, PIN unique par magasin, rôle attribué ≤ le sien.<br><i>Rôles par magasin ; OWNER et ADMIN portent sur tout le commerce : ils reçoivent leur rôle dans chaque nouveau magasin (lot R1), toujours stockés magasin par magasin.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-06, RG-MSTORE-07</td><td>0.x, 1.x, 2.18, R1</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-login-pin-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-invitation-email">📷</a></td></tr><tr><td><strong>Invitation dans plusieurs magasins</strong><br><span class="muted">Inviter un membre par email dans plusieurs magasins à la fois (« Aussi dans »), en étant MANAGER+ de chacun ; 404 pour un magasin d&#39;un autre tenant.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-06</td><td>2.24</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-equipe">📷</a></td></tr></tbody></table><h2 id="catalogue-multi-magasins" tabindex="-1">Catalogue multi-magasins <a class="header-anchor" href="#catalogue-multi-magasins" aria-label="Permalink to &quot;Catalogue multi-magasins&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Catalogue défini au niveau du tenant</strong><br><span class="muted">Définir produits et catégories une seule fois pour tous les magasins, et créer des produits locaux à un seul magasin.<br><i>Produits et catégories portés par l&#39;entreprise (code-barres unique dans l&#39;entreprise). Lot 3.11 : produit « Ce magasin uniquement » créé par un gérant du magasin d&#39;origine, envoyé aux seules caisses de ce magasin, badge et filtre « Produits locaux » au back-office. Reste : import CSV de produits locaux.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-03</td><td>0.x, 3.11</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-lots-front-existants">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-311d-produits-locaux">📷</a></td></tr><tr><td><strong>Surcharges prix / TVA / disponibilité par magasin</strong><br><span class="muted">Surcharger dans un magasin le prix, la TVA ou la disponibilité d&#39;un produit du tenant, résolus de façon identique sur la caisse et le serveur ; refus explicite au scan d&#39;un produit non vendu dans ce magasin.<br><i>Lot 3.11b : fiche produit web « Prix par magasin » (prix, TVA du référentiel, disponibilité ; vide = hérite ; rétablir), MANAGER du magasin, journal d&#39;audit ; surcharge envoyée aux seules caisses du magasin et résolue par le moteur partagé (prix et TVA à la vente, produit retiré des listes et boutons rapides) ; scan refusé « Produit non vendu dans ce magasin » sur Android et iOS, code-barres toujours trouvé pour l&#39;inventaire.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-04, RG-MSTORE-05</td><td>3.11b</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-311b-prix-par-magasin">📷</a></td></tr><tr><td><strong>Promotion d&#39;un produit local vers le tenant</strong><br><span class="muted">Promouvoir (ADMIN, irréversible) un produit local en produit du tenant pour pouvoir le transférer.<br><i>Lot 3.11 : « Rendre disponible dans tous les magasins » (propriétaire / administrateur, irréversible, journal d&#39;audit) : le produit local devient celui de l&#39;entreprise et part vers toutes les caisses ; avant cela, surcharge et transfert depuis un autre magasin sont refusés.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-13</td><td>3.11</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-311d-produits-locaux">📷</a></td></tr></tbody></table><h2 id="transferts-de-stock" tabindex="-1">Transferts de stock <a class="header-anchor" href="#transferts-de-stock" aria-label="Permalink to &quot;Transferts de stock&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Workflow de transfert</strong><br><span class="muted">Demander, valider (quantités ajustables), rejeter, expédier, réceptionner ou annuler un transfert entre deux magasins, sans saut d&#39;état (409), transfert « poussé » possible par le magasin source.<br><i>Lot 3.11a : demande par la destination ou envoi « poussé » par la source, validation ligne à ligne (quantités ajustables), rejet et annulation motivés avant expédition, expédition, réception ; aucun saut d&#39;état (409) ; numéro TR-AAAA-NNNN, bon PDF, journal d&#39;audit ; page web Transferts. Les caisses ne manipulent pas les transferts : elles reçoivent les mouvements de stock.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-09, RG-MSTORE-12</td><td>3.11a</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-311a-transferts">📷</a></td></tr><tr><td><strong>Stock en transit et mouvements TRANSFER_</strong>*<br><span class="muted">Sortir le stock expédié du vendable (TRANSFER_OUT), le suivre en transit puis l&#39;entrer à destination pour la quantité comptée (TRANSFER_IN).<br><i>Lot 3.11a : TRANSFER_OUT par ligne à l&#39;expédition, émis vers les caisses du magasin source (stock vendable en baisse, prouvé sur Android et iPhone) ; quantité en transit calculée (jamais stockée) ; TRANSFER_IN de la quantité comptée vers la destination, CMP recalculé au coût source si même devise.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-10</td><td>3.11a</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-311a-transferts">📷</a></td></tr><tr><td><strong>Écarts de réception tracés</strong><br><span class="muted">Saisir un motif obligatoire par ligne en écart (422 sinon), sous PIN manager, avec ajustement TRANSFER_DISCREPANCY imputé au magasin source et entrée d&#39;audit.<br><i>Lot 3.11a : motif obligatoire par ligne en écart (422), PIN d&#39;un gérant (propriétaire et administrateurs dispensés), entrée d&#39;audit ; écart valorisé au coût d&#39;expédition et imputé au magasin source (« Écart de transfert » dans ses pertes). Écart à la spec : pas de mouvement TRANSFER_DISCREPANCY, qui compterait la perte deux fois.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-11</td><td>3.11a</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-311a-transferts">📷</a></td></tr><tr><td><strong>Réception sur tablette et bon d&#39;expédition</strong><br><span class="muted">Imprimer le bon d&#39;expédition et réceptionner un transfert sur tablette par scan, y compris hors ligne (le serveur départage une double réception).<br><i>Lot 3.11a : bon d&#39;expédition / de réception PDF ; réception sur la caisse ou la tablette du magasin destination (Android et iOS, responsables) : comptage à l&#39;aveugle au +/− et au scan, motif et PIN si écart, réception en ligne (hors ligne refusée avec message, double réception départagée par le serveur : « déjà reçu par … ») ; alerte aux responsables de l&#39;autre magasin.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td></td><td>3.11a, 3.11</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-311a-transferts">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-01-311e-transferts-caisse">📷</a></td></tr></tbody></table><h2 id="clients-fournisseurs" tabindex="-1">Clients &amp; fournisseurs <a class="header-anchor" href="#clients-fournisseurs" aria-label="Permalink to &quot;Clients &amp; fournisseurs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Clients, fidélité et ardoise partagés</strong><br><span class="muted">Cumuler et utiliser points et ardoise dans tous les magasins, avec option de restriction par magasin (loyaltyScope / creditScope).<br><i>Clients et ardoises portés par l&#39;entreprise, donc communs à tous ses magasins (lots 3.1, 3.4) ; fidélité au périmètre entreprise ou magasin (lot 3.3) ; vues consolidées avec le lot 3.11 multi-magasins.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-MSTORE-14</td><td></td><td></td></tr><tr><td><strong>Fournisseurs partagés et commandes groupées</strong><br><span class="muted">Partager les fournisseurs au niveau du tenant et regrouper des commandes par magasin, chaque réception restant locale.<br><i>Phase 3 — dépend des fournisseurs et achats (spec 07).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-MSTORE-15</td><td></td><td></td></tr></tbody></table><h2 id="synchronisation" tabindex="-1">Synchronisation <a class="header-anchor" href="#synchronisation" aria-label="Permalink to &quot;Synchronisation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Appareil rattaché à un seul magasin</strong><br><span class="muted">Appairer chaque appareil à un magasin précis ; changer de magasin impose un désappairage puis un ré-appairage (outbox réconciliée sous la nouvelle identité).</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-MSTORE-08</td><td>0.x, 1.x, 2.8</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-appairage-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-operations-addition">📷</a></td></tr><tr><td><strong>Scoping de la synchronisation par magasin</strong><br><span class="muted">Ne faire recevoir à un appareil que les événements de son magasin : ventes, sessions et stock d&#39;un autre magasin ne lui parviennent jamais.<br><i>Pull filtré par store_id et RLS faits ; les événements tenant-level (catalogue, modificateurs, marque) sont republiés vers chaque magasin au lieu d&#39;un flux storeId = null ; double émission des transferts à faire avec eux.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-MSTORE-18</td><td>0.x, 1.x, 2.3</td><td></td></tr></tbody></table><h2 id="theme-reporting" tabindex="-1">Thème &amp; reporting <a class="header-anchor" href="#theme-reporting" aria-label="Permalink to &quot;Thème &amp; reporting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Thème par magasin hérité de la marque</strong><br><span class="muted">Donner à chaque magasin son thème, héritant champ par champ du thème de marque du tenant.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-16</td><td>1.x, 2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-design-tokens-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Reporting consolidé tous magasins</strong><br><span class="muted">Consulter les totaux, la comparaison côte à côte et le classement des magasins, sans conversion de devises.<br><i>Lot 3.11c : page « Comparaison des magasins » (propriétaire et administrateurs) — totaux par devise, comparaison côte à côte et classement par CA, tickets, panier moyen, marge ou taux, évolution vs la période précédente, produit phare, fraîcheur ; pas de conversion entre devises ; export CSV.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-MSTORE-17</td><td>3.11c</td><td><a href="/VendoraSystem-docs/preuves/2026-11-01-311c-comparaison-magasins">📷</a></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Rôles OWNER / ADMIN au niveau du tenant et endpoints d&#39;affectation / retrait de rôle par magasin.</li><li>Import CSV de produits locaux.</li><li>Transferts : réception hors ligne (aujourd&#39;hui en ligne seulement).</li><li>Clients, fidélité et ardoise partagés (avec option par magasin) ; fournisseurs partagés et commandes groupées.</li><li>Flux d&#39;événements tenant-level dédié (storeId = null) et double émission des transferts.</li><li>Horaires d&#39;ouverture et TVA par défaut par magasin.</li></ul>',20)])])}const m=t(d,[["render",r]]);export{g as __pageData,m as default};
